@CrossOrigin
@RestController
@RequestMapping("/CouponQuery")
public class CouponQueryRestController extends BaseSpringRestController {
	
	public CouponQueryRestController( CouponService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Coupon using a UUID
     * @param		UUID couponId
     * @return		Coupon
     */    
    @GetMapping("/load")
    public Coupon load( @RequestParam(required=true) UUID couponId ) {
    	Coupon entity = null;

    	try {  
    		entity = service.getCoupon( new CouponFetchOneSummary( couponId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Coupon using Id " + couponId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Coupon business objects
     * @return		Set<Coupon>
     */
    @GetMapping("/")
    public List<Coupon> loadAll() {                
    	List<Coupon> couponList = null;
        
    	try {
            // load the Coupon
            couponList = service.getAllCoupon();
            
            if ( couponList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Coupons" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Coupons ", exc );
        	return null;
        }

        return couponList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Coupon coupon = null;
    protected CouponService service = null;
    private static final Logger LOGGER = Logger.getLogger(CouponQueryRestController.class.getName());
    
}
